import { useCallback, useEffect, useState } from 'react';
import clsx from 'clsx';
import { Copy } from 'lucide-react';
import './index.css';
import type { ContactDraft, Project, Route } from './lib/types';
import { useStore } from './lib/store';
import { STUDIO } from './data/studio';
import Work from './components/Work';
import ProjectPage from './components/ProjectPage';
import ProjectEditor from './components/ProjectEditor';
import Services from './components/Services';
import Studio from './components/Studio';
import Contact from './components/Contact';
import { Toast } from './components/ui';

const NAV: { name: Route['name']; label: string }[] = [
  { name: 'trabajo', label: 'Trabajo' },
  { name: 'estudio', label: 'Estudio' },
  { name: 'servicios', label: 'Servicios' },
  { name: 'contacto', label: 'Contacto' },
];

function readRoute(): Route {
  const h = window.location.hash.replace(/^#\/?/, '');
  const [a, b] = h.split('/');
  if (a === 'proyecto' && b) return { name: 'proyecto', id: decodeURIComponent(b) };
  if (a === 'servicios' || a === 'estudio' || a === 'contacto') return { name: a };
  return { name: 'trabajo' };
}

function toHash(r: Route) {
  return r.name === 'proyecto' ? `#/proyecto/${r.id}` : r.name === 'trabajo' ? '#/' : `#/${r.name}`;
}

export default function App() {
  const store = useStore();
  const [route, setRoute] = useState<Route>(readRoute);
  const [editing, setEditing] = useState<Project | 'nuevo' | null>(null);
  const [draft, setDraft] = useState<ContactDraft>({});
  const [toast, setToast] = useState<string | null>(null);

  useEffect(() => {
    const on = () => setRoute(readRoute());
    window.addEventListener('hashchange', on);
    return () => window.removeEventListener('hashchange', on);
  }, []);

  const go = useCallback((r: Route) => {
    setRoute(r);
    try { window.history.replaceState(null, '', toHash(r)); } catch { /* vista previa sin historial */ }
    window.scrollTo({ top: 0 });
  }, []);

  const requestQuote = useCallback((d: ContactDraft) => { setDraft(d); go({ name: 'contacto' }); }, [go]);
  const closeToast = useCallback(() => setToast(null), []);

  const copyEmail = () => {
    try { navigator.clipboard?.writeText(STUDIO.email); } catch { /* sin portapapeles */ }
    setToast('Correo copiado: ' + STUDIO.email);
  };

  const current = route.name === 'proyecto' ? 'trabajo' : route.name;
  const project = route.name === 'proyecto' ? store.projects.find(p => p.id === route.id) : undefined;

  return (
    <div className="lm min-h-screen bg-[#F5F5F2] text-[#141414]">
      <header className="sticky top-0 z-40 border-b border-[#D8D8D2] bg-[#F5F5F2]/95 backdrop-blur">
        <div className="mx-auto flex max-w-[1360px] flex-wrap items-center justify-between gap-x-6 gap-y-1 px-5 py-3 sm:px-8 sm:py-4">
          <p className="flex items-baseline gap-2">
            <button onClick={() => go({ name: 'trabajo' })} className="lm-serif text-[28px] leading-none" aria-label="Ir a la portada">Lucía Marín</button>
            <span className="text-sm text-[#55575D]" aria-hidden>Estudio</span>
          </p>
          <nav aria-label="Principal" className="-mx-1 flex w-full gap-5 overflow-x-auto px-1 pb-1 sm:w-auto sm:gap-8 sm:pb-0">
            {NAV.map(n => (
              <button
                key={n.name}
                onClick={() => go({ name: n.name } as Route)}
                aria-current={current === n.name ? 'page' : undefined}
                className={clsx('lm-link whitespace-nowrap py-1 text-[15px]', current === n.name ? 'text-[#141414]' : 'text-[#55575D] hover:text-[#141414]')}
              >
                {n.label}
              </button>
            ))}
          </nav>
        </div>
      </header>

      <main>
        {route.name === 'trabajo' && <Work projects={store.projects} go={go} onAdd={() => setEditing('nuevo')} />}
        {route.name === 'proyecto' && (project
          ? <ProjectPage key={project.id} project={project} projects={store.projects} go={go} onEdit={() => setEditing(project)} />
          : (
            <section className="mx-auto max-w-[1360px] px-5 py-28 sm:px-8">
              <h1 className="lm-serif text-6xl">Este proyecto ya no está publicado.</h1>
              <button onClick={() => go({ name: 'trabajo' })} className="mt-8 border-b border-[#141414] pb-0.5">Ver todo el trabajo</button>
            </section>
          ))}
        {route.name === 'servicios' && <Services onQuote={requestQuote} />}
        {route.name === 'estudio' && <Studio go={go} />}
        {route.name === 'contacto' && <Contact store={store} draft={draft} onToast={setToast} />}
      </main>

      <footer className="mt-24 bg-[#141414] text-[#F5F5F2]">
        <div className="mx-auto max-w-[1360px] px-5 pb-28 pt-16 sm:px-8">
          <p className="text-[#B9B9B3]">¿Tienes un proyecto entre manos?</p>
          <button onClick={() => go({ name: 'contacto' })} className="lm-serif lm-link mt-2 text-left text-[44px] leading-[1.05] sm:text-[88px]">
            Escríbeme y lo hablamos.
          </button>
          <div className="mt-14 grid gap-8 border-t border-white/15 pt-8 text-sm text-[#D5D5CF] sm:grid-cols-4">
            <div>
              <p className="text-white">{STUDIO.email}</p>
              <button onClick={copyEmail} className="mt-2 inline-flex items-center gap-1.5 text-[#B9B9B3] hover:text-white"><Copy size={14} /> Copiar correo</button>
            </div>
            <p>{STUDIO.phone}<br />Calle Sueca 28, bajo · {STUDIO.city}</p>
            <p>Instagram {STUDIO.instagram}<br />Lunes a viernes, 9–18 h</p>
            <div>
              <p>© 2026 Lucía Marín Estudio</p>
              <button
                onClick={() => { if (window.confirm('¿Restablecer los proyectos y solicitudes de ejemplo? Se perderán tus cambios.')) { store.reset(); setToast('Datos de ejemplo restablecidos'); go({ name: 'trabajo' }); } }}
                className="mt-2 text-[#B9B9B3] underline-offset-4 hover:text-white hover:underline"
              >
                Restablecer datos de ejemplo
              </button>
            </div>
          </div>
        </div>
      </footer>

      {editing && (
        <ProjectEditor
          project={editing === 'nuevo' ? null : editing}
          onClose={() => setEditing(null)}
          onSave={p => { store.saveProject(p); setEditing(null); setToast(editing === 'nuevo' ? 'Proyecto publicado' : 'Cambios guardados'); go({ name: 'proyecto', id: p.id }); }}
          onDelete={id => { store.deleteProject(id); setEditing(null); setToast('Proyecto eliminado'); go({ name: 'trabajo' }); }}
        />
      )}
      <Toast text={toast} onClose={closeToast} />
    </div>
  );
}

import { useRef, useState, type FormEvent } from 'react';
import confetti from 'canvas-confetti';
import { Trash2 } from 'lucide-react';
import type { ContactDraft } from '../lib/types';
import type { Store } from '../lib/store';
import { BUDGETS, KINDS, STUDIO } from '../data/studio';
import { isEmail, relative, uid } from '../lib/format';
import { Field } from './ui';

type Form = { name: string; email: string; company: string; kind: string; budget: string; when: string; message: string; consent: boolean };
type Errors = Partial<Record<keyof Form, string>>;
type Props = { store: Store; draft: ContactDraft; onToast: (t: string) => void };

const ORDER: (keyof Form)[] = ['name', 'email', 'kind', 'budget', 'message', 'consent'];

function validate(f: Form): Errors {
  const e: Errors = {};
  if (f.name.trim().length < 2) e.name = 'Dime cómo te llamas.';
  if (!isEmail(f.email)) e.email = 'Revisa el correo: necesito uno válido para responderte.';
  if (!f.kind) e.kind = 'Elige el tipo de proyecto.';
  if (!f.budget) e.budget = 'Elige un rango, aunque sea aproximado.';
  if (f.message.trim().length < 30) e.message = `Cuéntame un poco más (mínimo 30 caracteres, llevas ${f.message.trim().length}).`;
  if (!f.consent) e.consent = 'Necesito tu permiso para guardar estos datos.';
  return e;
}

export default function Contact({ store, draft, onToast }: Props) {
  const empty: Form = { name: '', email: '', company: '', kind: draft.kind ?? '', budget: draft.budget ?? '', when: '', message: draft.message ?? '', consent: false };
  const [f, setF] = useState<Form>(empty);
  const [errors, setErrors] = useState<Errors>({});
  const [sent, setSent] = useState<string | null>(null);
  const formRef = useRef<HTMLFormElement>(null);

  const set = <K extends keyof Form>(k: K, v: Form[K]) => { setF(x => ({ ...x, [k]: v })); if (errors[k]) setErrors(e => ({ ...e, [k]: undefined })); };

  const submit = (ev: FormEvent) => {
    ev.preventDefault();
    const e = validate(f);
    setErrors(e);
    const first = ORDER.find(k => e[k]);
    if (first) { formRef.current?.querySelector<HTMLElement>(`[name="${first}"]`)?.focus(); return; }
    store.addInquiry({ id: uid(), name: f.name.trim(), email: f.email.trim(), company: f.company.trim(), kind: f.kind, budget: f.budget, when: f.when, message: f.message.trim(), createdAt: Date.now() });
    setSent(f.name.trim().split(' ')[0]);
    setF({ ...empty, kind: '', budget: '', message: '' });
    try { confetti({ particleCount: 60, spread: 60, origin: { y: 0.7 }, colors: ['#2633C9', '#F1CFC6', '#141414'], disableForReducedMotion: true }); } catch { /* sin canvas */ }
  };

  return (
    <div className="lm-fade mx-auto max-w-[1360px] px-5 pt-12 sm:px-8">
      <div className="grid gap-12 lg:grid-cols-12">
        <section className="lg:col-span-5">
          <h1 className="lm-serif text-[52px] leading-[0.95] sm:text-[88px]">Cuéntame tu proyecto</h1>
          <p className="mt-6 max-w-md text-lg leading-relaxed">Respondo en dos días laborables con preguntas o con una propuesta de llamada. {STUDIO.availability} de 2027.</p>
          <dl className="mt-10 border-t border-[#141414] text-[15px]">
            {[['Correo', STUDIO.email], ['Teléfono', STUDIO.phone], ['Estudio', 'Calle Sueca 28, bajo · Valencia'], ['Instagram', STUDIO.instagram]].map(([k, v]) => (
              <div key={k} className="grid grid-cols-[100px_1fr] gap-3 border-b border-[#D8D8D2] py-2.5"><dt className="text-[#55575D]">{k}</dt><dd>{v}</dd></div>
            ))}
          </dl>
        </section>

        <section className="lg:col-span-6 lg:col-start-7">
          {sent ? (
            <div role="status" className="lm-pop bg-[#F1CFC6] p-8 sm:p-10">
              <p className="lm-serif text-[44px] leading-none">Gracias, {sent}.</p>
              <p className="mt-4 text-lg">Tu mensaje ha llegado. Te escribiré antes de dos días laborables desde {STUDIO.email}.</p>
              <button onClick={() => setSent(null)} className="mt-6 border-b border-[#141414] pb-0.5">Enviar otro mensaje</button>
            </div>
          ) : (
            <form ref={formRef} onSubmit={submit} noValidate className="grid gap-7 sm:grid-cols-2">
              <Field label="Nombre" error={errors.name}>
                <input name="name" autoComplete="name" className="lm-field" value={f.name} onChange={e => set('name', e.target.value)} aria-invalid={!!errors.name} />
              </Field>
              <Field label="Correo electrónico" error={errors.email}>
                <input name="email" type="email" autoComplete="email" className="lm-field" value={f.email} onChange={e => set('email', e.target.value)} aria-invalid={!!errors.email} />
              </Field>
              <Field label="Empresa o marca (opcional)">
                <input name="company" className="lm-field" value={f.company} onChange={e => set('company', e.target.value)} />
              </Field>
              <Field label="Tipo de proyecto" error={errors.kind}>
                <select name="kind" className="lm-field" value={f.kind} onChange={e => set('kind', e.target.value)} aria-invalid={!!errors.kind}>
                  <option value="">Elige una opción</option>
                  {KINDS.map(k => <option key={k}>{k}</option>)}
                </select>
              </Field>
              <Field label="Presupuesto" error={errors.budget}>
                <select name="budget" className="lm-field" value={f.budget} onChange={e => set('budget', e.target.value)} aria-invalid={!!errors.budget}>
                  <option value="">Elige un rango</option>
                  {BUDGETS.map(b => <option key={b}>{b}</option>)}
                </select>
              </Field>
              <Field label="¿Para cuándo? (opcional)">
                <input name="when" type="month" min="2026-10" className="lm-field" value={f.when} onChange={e => set('when', e.target.value)} />
              </Field>
              <div className="sm:col-span-2">
                <Field label="Mensaje" error={errors.message}>
                  <textarea name="message" rows={5} className="lm-field resize-y" value={f.message} onChange={e => set('message', e.target.value)} aria-invalid={!!errors.message}
                    placeholder="Qué quieres hacer, para quién y qué te gustaría conseguir." />
                </Field>
              </div>
              <div className="sm:col-span-2">
                <label className="flex items-start gap-3 text-[15px]">
                  <input name="consent" type="checkbox" checked={f.consent} onChange={e => set('consent', e.target.checked)} className="mt-1 h-4 w-4 accent-[#2633C9]" aria-invalid={!!errors.consent} />
                  Acepto que Lucía Marín guarde estos datos solo para responder a mi consulta.
                </label>
                {errors.consent && <p className="mt-1.5 text-sm text-[#B3261E]">{errors.consent}</p>}
              </div>
              <div className="sm:col-span-2">
                <button type="submit" className="w-full bg-[#2633C9] px-6 py-3.5 text-white hover:bg-[#1C27A3] sm:w-auto">Enviar mensaje</button>
              </div>
            </form>
          )}
        </section>
      </div>

      <section className="mt-20 border-t border-[#141414] pt-6">
        <div className="flex flex-wrap items-baseline justify-between gap-2">
          <h2 className="lm-serif text-[36px]">Solicitudes enviadas</h2>
          <p className="text-sm text-[#55575D]">Guardadas en este navegador</p>
        </div>
        {store.inquiries.length === 0 ? (
          <p className="py-8 text-[#55575D]">Todavía no has enviado ninguna. Cuando lo hagas, aparecerán aquí para que puedas revisarlas.</p>
        ) : (
          <ul>
            {store.inquiries.map(q => (
              <li key={q.id} className="grid gap-2 border-b border-[#D8D8D2] py-5 sm:grid-cols-[220px_1fr_auto] sm:gap-6">
                <div>
                  <p className="font-medium">{q.name}{q.company && <span className="font-normal text-[#55575D]"> · {q.company}</span>}</p>
                  <p className="text-sm text-[#55575D]">{relative(q.createdAt)}</p>
                </div>
                <div>
                  <p className="text-sm text-[#2633C9]">{q.kind} · {q.budget}</p>
                  <p className="mt-1 line-clamp-2 whitespace-pre-line text-[15px]">{q.message}</p>
                </div>
                <button onClick={() => { store.deleteInquiry(q.id); onToast('Solicitud eliminada'); }} aria-label={`Eliminar solicitud de ${q.name}`}
                  className="inline-flex items-center gap-1.5 self-start text-sm text-[#55575D] hover:text-[#B3261E]">
                  <Trash2 size={15} /> Eliminar
                </button>
              </li>
            ))}
          </ul>
        )}
      </section>
    </div>
  );
}

import { useState, type FormEvent } from 'react';
import clsx from 'clsx';
import { Check, Trash2 } from 'lucide-react';
import type { Discipline, Project } from '../lib/types';
import { DISCIPLINES, PHOTOS } from '../data/projects';
import { IMG } from '../data/images';
import { uid } from '../lib/format';
import { Field, Modal } from './ui';

type Props = { project: Project | null; onClose: () => void; onSave: (p: Project) => void; onDelete: (id: string) => void };
type Form = { title: string; client: string; year: string; discipline: Discipline; role: string; location: string; summary: string; body: string; cover: string; gallery: string[] };
type Errors = Partial<Record<keyof Form, string>>;

function validate(f: Form): Errors {
  const e: Errors = {};
  if (f.title.trim().length < 3) e.title = 'Pon un título de al menos 3 letras.';
  if (!f.client.trim()) e.client = 'Indica para quién fue el proyecto.';
  const y = Number(f.year);
  if (!Number.isInteger(y) || y < 2000 || y > 2027) e.year = 'Año entre 2000 y 2027.';
  if (f.summary.trim().length < 20) e.summary = 'Resume el proyecto en una frase (mín. 20 caracteres).';
  if (!f.cover) e.cover = 'Elige una portada.';
  return e;
}

export default function ProjectEditor({ project, onClose, onSave, onDelete }: Props) {
  const [f, setF] = useState<Form>(() => project
    ? { ...project, year: String(project.year), body: project.body.join('\n\n') }
    : { title: '', client: '', year: '2026', discipline: 'Fotografía', role: '', location: 'Valencia', summary: '', body: '', cover: '', gallery: [] });
  const [errors, setErrors] = useState<Errors>({});
  const [confirmDel, setConfirmDel] = useState(false);

  const set = <K extends keyof Form>(k: K, v: Form[K]) => { setF(x => ({ ...x, [k]: v })); setErrors(e => ({ ...e, [k]: undefined })); };
  const toggleGallery = (n: string) => set('gallery', f.gallery.includes(n) ? f.gallery.filter(x => x !== n) : [...f.gallery, n]);

  const submit = (ev: FormEvent) => {
    ev.preventDefault();
    const e = validate(f);
    setErrors(e);
    if (Object.keys(e).length) return;
    const gallery = [f.cover, ...f.gallery.filter(g => g !== f.cover)];
    onSave({
      id: project?.id ?? `${f.title.toLowerCase().normalize('NFD').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 30)}-${uid().slice(0, 3)}`,
      title: f.title.trim(), client: f.client.trim(), year: Number(f.year), discipline: f.discipline,
      role: f.role.trim() || f.discipline, location: f.location.trim() || '—', summary: f.summary.trim(),
      body: f.body.split(/\n\s*\n/).map(s => s.trim()).filter(Boolean), cover: f.cover, gallery,
      swatches: project?.swatches ?? [], featured: project?.featured,
    });
  };

  const photos = Object.keys(PHOTOS);

  return (
    <Modal title={project ? 'Editar proyecto' : 'Nuevo proyecto'} onClose={onClose} wide>
      <form onSubmit={submit} noValidate className="grid gap-6 sm:grid-cols-2">
        <Field label="Título" error={errors.title}>
          <input className="lm-field" value={f.title} onChange={e => set('title', e.target.value)} aria-invalid={!!errors.title} placeholder="Casa en la Albufera" />
        </Field>
        <Field label="Cliente" error={errors.client}>
          <input className="lm-field" value={f.client} onChange={e => set('client', e.target.value)} aria-invalid={!!errors.client} placeholder="Nombre del cliente" />
        </Field>
        <Field label="Disciplina">
          <select className="lm-field" value={f.discipline} onChange={e => set('discipline', e.target.value as Discipline)}>
            {DISCIPLINES.map(d => <option key={d}>{d}</option>)}
          </select>
        </Field>
        <div className="grid grid-cols-2 gap-5">
          <Field label="Año" error={errors.year}>
            <input className="lm-field lm-num" inputMode="numeric" value={f.year} onChange={e => set('year', e.target.value)} aria-invalid={!!errors.year} />
          </Field>
          <Field label="Lugar">
            <input className="lm-field" value={f.location} onChange={e => set('location', e.target.value)} />
          </Field>
        </div>
        <div className="sm:col-span-2">
          <Field label="Mi papel" hint="Por ejemplo: Fotografía y edición">
            <input className="lm-field" value={f.role} onChange={e => set('role', e.target.value)} />
          </Field>
        </div>
        <div className="sm:col-span-2">
          <Field label="Resumen" error={errors.summary}>
            <input className="lm-field" value={f.summary} onChange={e => set('summary', e.target.value)} aria-invalid={!!errors.summary} placeholder="Qué se hizo y para qué, en una frase" />
          </Field>
        </div>
        <div className="sm:col-span-2">
          <Field label="Texto del proyecto" hint="Separa los párrafos con una línea en blanco.">
            <textarea className="lm-field min-h-[96px] resize-y" value={f.body} onChange={e => set('body', e.target.value)} />
          </Field>
        </div>
        <fieldset className="sm:col-span-2">
          <legend className="text-sm text-[#55575D]">Portada (clic) y galería (casilla)</legend>
          <div className="mt-3 grid grid-cols-4 gap-2 sm:grid-cols-7">
            {photos.map(n => {
              const isCover = f.cover === n; const inGal = f.gallery.includes(n);
              return (
                <div key={n} className="relative">
                  <button type="button" onClick={() => set('cover', n)} aria-pressed={isCover} aria-label={`Usar como portada: ${PHOTOS[n]}`}
                    className={clsx('lm-photo block aspect-square w-full outline-offset-2', isCover && 'outline outline-2 outline-[#2633C9]')}>
                    <img src={IMG(n)} alt="" loading="lazy" className="h-full w-full object-cover" />
                  </button>
                  <button type="button" onClick={() => toggleGallery(n)} aria-pressed={inGal} aria-label={`${inGal ? 'Quitar de' : 'Añadir a'} la galería: ${PHOTOS[n]}`}
                    className={clsx('absolute right-1 top-1 grid h-5 w-5 place-items-center border', inGal ? 'border-[#2633C9] bg-[#2633C9] text-white' : 'border-white bg-black/25')}>
                    {inGal && <Check size={12} />}
                  </button>
                </div>
              );
            })}
          </div>
          {errors.cover && <p className="mt-2 text-sm text-[#B3261E]">{errors.cover}</p>}
        </fieldset>

        <div className="flex flex-wrap items-center gap-3 border-t border-[#D8D8D2] pt-5 sm:col-span-2">
          <button type="submit" className="bg-[#2633C9] px-5 py-2.5 text-white hover:bg-[#1C27A3]">{project ? 'Guardar cambios' : 'Publicar proyecto'}</button>
          <button type="button" onClick={onClose} className="px-3 py-2.5 text-[#55575D] hover:text-[#141414]">Cancelar</button>
          {project && (confirmDel ? (
            <span className="ml-auto flex items-center gap-2 text-sm">
              ¿Eliminar «{project.title}»?
              <button type="button" onClick={() => onDelete(project.id)} className="bg-[#B3261E] px-3 py-2 text-white">Sí, eliminar</button>
              <button type="button" onClick={() => setConfirmDel(false)} className="px-2 py-2">No</button>
            </span>
          ) : (
            <button type="button" onClick={() => setConfirmDel(true)} className="ml-auto inline-flex items-center gap-1.5 text-sm text-[#B3261E]"><Trash2 size={15} /> Eliminar proyecto</button>
          ))}
        </div>
      </form>
    </Modal>
  );
}

import { useCallback, useEffect, useState } from 'react';
import { ArrowLeft, ChevronLeft, ChevronRight, Expand, Pencil, X } from 'lucide-react';
import type { Project, Route } from '../lib/types';
import { IMG } from '../data/images';
import { PHOTOS } from '../data/projects';
import { Photo } from './ui';

type Props = { project: Project; projects: Project[]; go: (r: Route) => void; onEdit: () => void };

export default function ProjectPage({ project: p, projects, go, onEdit }: Props) {
  const [lightbox, setLightbox] = useState<number | null>(null);
  const images = p.gallery.length ? p.gallery : [p.cover];
  const idx = projects.findIndex(x => x.id === p.id);
  const next = projects[(idx + 1) % projects.length];

  const step = useCallback((d: number) => setLightbox(i => (i === null ? i : (i + d + images.length) % images.length)), [images.length]);

  useEffect(() => {
    if (lightbox === null) return;
    const k = (e: KeyboardEvent) => {
      if (e.key === 'Escape') setLightbox(null);
      if (e.key === 'ArrowRight') step(1);
      if (e.key === 'ArrowLeft') step(-1);
    };
    window.addEventListener('keydown', k);
    return () => window.removeEventListener('keydown', k);
  }, [lightbox, step]);

  const facts: [string, string][] = [
    ['Cliente', p.client], ['Año', String(p.year)], ['Disciplina', p.discipline], ['Mi papel', p.role], ['Lugar', p.location],
  ];

  return (
    <article className="lm-fade mx-auto max-w-[1360px] px-5 sm:px-8">
      <div className="flex items-center justify-between pt-6">
        <button onClick={() => go({ name: 'trabajo' })} className="inline-flex items-center gap-1.5 text-[15px] text-[#55575D] hover:text-[#141414]">
          <ArrowLeft size={16} /> Todo el trabajo
        </button>
        <button onClick={onEdit} className="inline-flex items-center gap-1.5 border border-[#C9C9C2] px-3 py-1.5 text-sm hover:border-[#141414]">
          <Pencil size={14} /> Editar proyecto
        </button>
      </div>

      <header className="grid gap-8 pb-10 pt-8 lg:grid-cols-12">
        <div className="lg:col-span-8">
          <p className="text-[15px] text-[#2633C9]">{p.discipline}</p>
          <h1 className="lm-serif mt-2 text-[56px] leading-[0.92] sm:text-[96px] lg:text-[118px]">{p.title}</h1>
          <p className="mt-6 max-w-2xl text-xl leading-snug sm:text-2xl">{p.summary}</p>
        </div>
        <dl className="self-end border-t border-[#141414] lg:col-span-4">
          {facts.map(([k, v]) => (
            <div key={k} className="grid grid-cols-[110px_1fr] gap-3 border-b border-[#D8D8D2] py-2.5 text-[15px]">
              <dt className="text-[#55575D]">{k}</dt>
              <dd className="lm-num">{v}</dd>
            </div>
          ))}
          {p.swatches.length > 0 && (
            <div className="grid grid-cols-[110px_1fr] items-center gap-3 py-3 text-[15px]">
              <dt className="text-[#55575D]">Paleta</dt>
              <dd className="flex gap-1.5">
                {p.swatches.map(c => <span key={c} title={c} className="h-6 w-6 rounded-full border border-black/10" style={{ background: c }} />)}
              </dd>
            </div>
          )}
        </dl>
      </header>

      <button onClick={() => setLightbox(0)} className="lm-card group relative block w-full" aria-label="Ver la galería a pantalla completa">
        <Photo name={images[0]} eager className="aspect-[16/9] w-full" />
        <span className="absolute bottom-4 right-4 inline-flex items-center gap-1.5 bg-[#F5F5F2] px-3 py-1.5 text-sm opacity-90 group-hover:opacity-100">
          <Expand size={14} /> {images.length} {images.length === 1 ? 'imagen' : 'imágenes'}
        </span>
      </button>

      <section className="grid gap-8 py-14 lg:grid-cols-12">
        <h2 className="lm-serif text-4xl lg:col-span-3">El encargo</h2>
        <div className="space-y-5 text-lg leading-relaxed lg:col-span-7 lg:col-start-5">
          {p.body.map((t, i) => <p key={i}>{t}</p>)}
        </div>
      </section>

      {images.length > 1 && (
        <section className="grid grid-cols-2 gap-4 sm:gap-6 lg:grid-cols-12">
          {images.slice(1).map((img, i) => (
            <button
              key={img + i}
              onClick={() => setLightbox(i + 1)}
              className={`lm-card block text-left ${i % 3 === 0 ? 'col-span-2 lg:col-span-7' : 'lg:col-span-5'}`}
              aria-label={`Ampliar: ${PHOTOS[img] ?? 'imagen'}`}
            >
              <Photo name={img} className={i % 3 === 0 ? 'aspect-[4/3]' : 'aspect-[4/5]'} />
              <span className="mt-2 block text-sm text-[#55575D]">{PHOTOS[img]}</span>
            </button>
          ))}
        </section>
      )}

      {next && next.id !== p.id && (
        <button onClick={() => go({ name: 'proyecto', id: next.id })} className="group mt-20 grid w-full items-end gap-6 border-t border-[#141414] pt-6 text-left sm:grid-cols-[1fr_260px]">
          <span>
            <span className="text-[15px] text-[#55575D]">Siguiente proyecto</span>
            <span className="lm-serif block text-[52px] leading-none transition-colors group-hover:text-[#2633C9] sm:text-[88px]">{next.title}</span>
          </span>
          <Photo name={next.cover} className="aspect-[4/3]" />
        </button>
      )}

      {lightbox !== null && (
        <div role="dialog" aria-modal="true" aria-label="Galería" className="fixed inset-0 z-50 flex flex-col bg-[#141414] text-white">
          <div className="flex items-center justify-between px-5 py-4 text-sm">
            <span className="lm-num">{p.title} · {lightbox + 1} de {images.length}</span>
            <button onClick={() => setLightbox(null)} aria-label="Cerrar galería" className="p-2 hover:text-[#F1CFC6]"><X size={22} /></button>
          </div>
          <div className="relative flex min-h-0 flex-1 items-center justify-center px-4 pb-6 sm:px-20">
            <img key={lightbox} src={IMG(images[lightbox])} alt={PHOTOS[images[lightbox]] ?? p.title} className="lm-pop max-h-full max-w-full object-contain" />
            {images.length > 1 && (
              <>
                <button onClick={() => step(-1)} aria-label="Imagen anterior" className="absolute left-2 top-1/2 -translate-y-1/2 p-3 hover:text-[#F1CFC6] sm:left-6"><ChevronLeft size={32} /></button>
                <button onClick={() => step(1)} aria-label="Imagen siguiente" className="absolute right-2 top-1/2 -translate-y-1/2 p-3 hover:text-[#F1CFC6] sm:right-6"><ChevronRight size={32} /></button>
              </>
            )}
          </div>
          <p className="px-5 pb-16 text-center text-sm text-[#B9B9B3]">{PHOTOS[images[lightbox]]}</p>
        </div>
      )}
    </article>
  );
}

import { useMemo, useState } from 'react';
import clsx from 'clsx';
import { Check, Minus, Plus } from 'lucide-react';
import type { ContactDraft } from '../lib/types';
import { SERVICES, TESTIMONIALS, USAGE, BUDGETS } from '../data/studio';
import { eur } from '../lib/format';
import { Photo } from './ui';

const KIND_BY_SERVICE: Record<string, string> = { foto: 'Fotografía', identidad: 'Identidad visual', arte: 'Dirección de arte', editorial: 'Diseño editorial' };

export default function Services({ onQuote }: { onQuote: (d: ContactDraft) => void }) {
  const [picked, setPicked] = useState<string[]>(['identidad', 'foto']);
  const [days, setDays] = useState(2);
  const [usage, setUsage] = useState('local');
  const [rush, setRush] = useState(false);
  const [t, setT] = useState(0);

  const lines = useMemo(() => {
    const factor = USAGE.find(u => u.id === usage)!.factor;
    return SERVICES.filter(s => picked.includes(s.id)).map(s => {
      let amount = s.id === 'foto' ? s.from * days : s.from;
      if (s.id === 'foto' || s.id === 'arte') amount *= factor;
      return { id: s.id, label: s.id === 'foto' ? `${s.name} · ${days} ${days === 1 ? 'jornada' : 'jornadas'}` : s.name, amount: Math.round(amount) };
    });
  }, [picked, days, usage]);

  const subtotal = lines.reduce((a, l) => a + l.amount, 0);
  const total = Math.round(subtotal * (rush ? 1.2 : 1));
  const toggle = (id: string) => setPicked(p => (p.includes(id) ? p.filter(x => x !== id) : [...p, id]));

  const quote = () => {
    const budget = total < 1500 ? BUDGETS[0] : total < 3000 ? BUDGETS[1] : total < 6000 ? BUDGETS[2] : BUDGETS[3];
    const kind = picked.length === 1 ? KIND_BY_SERVICE[picked[0]] : picked.length ? KIND_BY_SERVICE[picked[0]] : 'Otro';
    const detail = lines.map(l => `· ${l.label}`).join('\n');
    onQuote({ kind, budget, message: `Hola, Lucía. Me interesa:\n${detail}\nUso: ${USAGE.find(u => u.id === usage)!.label}${rush ? ' (con urgencia)' : ''}. Presupuesto orientativo: ${eur(total)}.\n\n` });
  };

  const tm = TESTIMONIALS[t];

  return (
    <div className="lm-fade">
      <section className="mx-auto max-w-[1360px] px-5 pt-12 sm:px-8">
        <h1 className="lm-serif max-w-5xl text-[52px] leading-[0.95] sm:text-[96px]">Servicios y tarifas</h1>
        <p className="mt-6 max-w-2xl text-lg text-[#55575D] sm:text-xl">
          Precios de partida con IVA no incluido. Cada encargo empieza con una llamada de 30 minutos, sin coste, para entender qué necesitas.
        </p>

        <div className="mt-12 border-t border-[#141414]">
          {SERVICES.map(s => (
            <div key={s.id} className="grid gap-4 border-b border-[#D8D8D2] py-8 lg:grid-cols-12">
              <h2 className="lm-serif text-[34px] leading-tight sm:text-[42px] lg:col-span-4">{s.name}</h2>
              <div className="lg:col-span-5">
                <p className="text-lg leading-snug">{s.lead}</p>
                <ul className="mt-3 space-y-1 text-[15px] text-[#55575D]">
                  {s.includes.map(i => <li key={i} className="flex gap-2"><Check size={15} className="mt-1 shrink-0 text-[#2633C9]" /> {i}</li>)}
                </ul>
              </div>
              <div className="lg:col-span-3 lg:text-right">
                <p className="lm-serif text-[40px] leading-none">desde {eur(s.from)}</p>
                <p className="mt-1 text-[15px] text-[#55575D]">{s.unit} · {s.time}</p>
              </div>
            </div>
          ))}
        </div>
      </section>

      <section className="lm-on-blue mt-20 bg-[#2633C9] text-white">
        <div className="mx-auto grid max-w-[1360px] gap-10 px-5 py-16 sm:px-8 lg:grid-cols-12">
          <div className="lg:col-span-5">
            <h2 className="lm-serif text-[48px] leading-none sm:text-[64px]">Calcula un presupuesto orientativo</h2>
            <p className="mt-4 text-lg text-white/85">Marca lo que necesitas. Te daré un precio cerrado después de la primera llamada.</p>
          </div>
          <div className="lg:col-span-7">
            <fieldset>
              <legend className="mb-3 text-white/85">Servicios</legend>
              <div className="grid gap-2 sm:grid-cols-2">
                {SERVICES.map(s => {
                  const on = picked.includes(s.id);
                  return (
                    <button key={s.id} onClick={() => toggle(s.id)} aria-pressed={on}
                      className={clsx('flex items-center gap-3 border px-4 py-3 text-left transition-colors', on ? 'border-white bg-white text-[#141414]' : 'border-white/40 hover:border-white')}>
                      <span className={clsx('grid h-5 w-5 shrink-0 place-items-center border', on ? 'border-[#2633C9] bg-[#2633C9] text-white' : 'border-white/70')}>{on && <Check size={13} />}</span>
                      {s.name}
                    </button>
                  );
                })}
              </div>
            </fieldset>

            <div className="mt-7 grid gap-7 sm:grid-cols-2">
              <div className={clsx(!picked.includes('foto') && 'opacity-50')}>
                <p className="text-white/85">Jornadas de fotografía</p>
                <div className="mt-2 flex items-center gap-4">
                  <button aria-label="Una jornada menos" disabled={!picked.includes('foto') || days <= 1} onClick={() => setDays(d => d - 1)} className="grid h-9 w-9 place-items-center border border-white/60 disabled:opacity-40"><Minus size={16} /></button>
                  <span className="lm-serif lm-num w-8 text-center text-4xl">{days}</span>
                  <button aria-label="Una jornada más" disabled={!picked.includes('foto') || days >= 10} onClick={() => setDays(d => d + 1)} className="grid h-9 w-9 place-items-center border border-white/60 disabled:opacity-40"><Plus size={16} /></button>
                </div>
              </div>
              <div>
                <p className="text-white/85">Uso de las imágenes</p>
                <div className="mt-2 flex flex-wrap gap-2">
                  {USAGE.map(u => (
                    <button key={u.id} onClick={() => setUsage(u.id)} aria-pressed={usage === u.id}
                      className={clsx('rounded-full border px-3 py-1.5 text-sm', usage === u.id ? 'border-white bg-white text-[#141414]' : 'border-white/50 hover:border-white')}>
                      {u.label}
                    </button>
                  ))}
                </div>
              </div>
            </div>
            <label className="mt-6 flex cursor-pointer items-center gap-3">
              <input type="checkbox" checked={rush} onChange={e => setRush(e.target.checked)} className="h-4 w-4 accent-[#F1CFC6]" />
              Lo necesito en menos de 3 semanas (+20 %)
            </label>

            <div className="mt-8 border-t border-white/40 pt-5">
              {lines.length === 0 ? <p className="text-white/85">Elige al menos un servicio para ver el cálculo.</p> : (
                <ul className="space-y-1.5 text-[15px] text-white/90">
                  {lines.map(l => <li key={l.id} className="flex justify-between gap-4"><span>{l.label}</span><span className="lm-num whitespace-nowrap">{eur(l.amount)}</span></li>)}
                  {rush && <li className="flex justify-between gap-4"><span>Urgencia</span><span className="lm-num whitespace-nowrap">{eur(total - subtotal)}</span></li>}
                </ul>
              )}
              <div className="mt-4 flex flex-wrap items-end justify-between gap-4">
                <p><span className="block text-white/85">Total orientativo</span><span className="lm-serif lm-num text-[64px] leading-none">{eur(total)}</span></p>
                <button onClick={quote} disabled={!lines.length} className="bg-white px-5 py-3 text-[#141414] hover:bg-[#F1CFC6] disabled:opacity-50">Pedir presupuesto con esta selección</button>
              </div>
            </div>
          </div>
        </div>
      </section>

      <section className="mx-auto max-w-[1360px] px-5 pt-20 sm:px-8">
        <h2 className="lm-serif text-[44px] sm:text-[56px]">Lo que dicen los clientes</h2>
        <figure key={t} className="lm-fade mt-8 grid items-center gap-8 bg-[#F1CFC6] p-6 sm:p-10 lg:grid-cols-[200px_1fr]">
          <Photo name={tm.photo} eager alt={`Retrato de ${tm.name}`} className="aspect-[4/5] w-32 sm:w-full" />
          <div>
            <blockquote className="lm-serif text-[28px] leading-[1.15] sm:text-[40px]">«{tm.quote}»</blockquote>
            <figcaption className="mt-5 text-[15px]"><strong className="font-semibold">{tm.name}</strong> · {tm.role}</figcaption>
          </div>
        </figure>
        <div className="mt-4 flex gap-2" role="tablist" aria-label="Testimonios">
          {TESTIMONIALS.map((x, i) => (
            <button key={x.name} role="tab" aria-selected={t === i} onClick={() => setT(i)}
              className={clsx('border-b-2 px-1 pb-1 text-sm', t === i ? 'border-[#141414]' : 'border-transparent text-[#55575D] hover:text-[#141414]')}>
              {x.name}
            </button>
          ))}
        </div>
      </section>
    </div>
  );
}

import { useMemo, useState } from 'react';
import clsx from 'clsx';
import { LayoutGrid, List, Plus, Search, X } from 'lucide-react';
import type { Discipline, Project, Route } from '../lib/types';
import { DISCIPLINES } from '../data/projects';
import { STUDIO } from '../data/studio';
import { usePref } from '../lib/store';
import { Photo, Pill } from './ui';
import { IMG } from '../data/images';

type Props = { projects: Project[]; go: (r: Route) => void; onAdd: () => void };
type Filter = 'Todo' | Discipline;

/** Ritmo de la rejilla: anchos (de 12 columnas), proporción y desfase vertical. */
const LAYOUT = [
  'lg:col-span-7 aspect-[4/3]',
  'lg:col-span-5 aspect-[4/5]',
  'lg:col-span-4 aspect-[3/4]',
  'lg:col-span-4 aspect-[3/4] lg:mt-16',
  'lg:col-span-4 aspect-[3/4]',
  'lg:col-span-5 aspect-[4/5]',
  'lg:col-span-7 aspect-[4/3] lg:mt-24',
];

export default function Work({ projects, go, onAdd }: Props) {
  const [filter, setFilter] = usePref<Filter>('filtro', 'Todo');
  const [view, setView] = usePref<'rejilla' | 'indice'>('vista', 'rejilla');
  const [q, setQ] = useState('');
  const [hover, setHover] = useState<{ img: string; x: number; y: number } | null>(null);

  const list = useMemo(() => {
    const t = q.trim().toLowerCase();
    return projects
      .filter(p => filter === 'Todo' || p.discipline === filter)
      .filter(p => !t || [p.title, p.client, p.location, p.discipline].join(' ').toLowerCase().includes(t));
  }, [projects, filter, q]);

  const count = (d: Filter) => (d === 'Todo' ? projects.length : projects.filter(p => p.discipline === d).length);
  const open = (p: Project) => go({ name: 'proyecto', id: p.id });

  return (
    <div className="mx-auto max-w-[1360px] px-5 sm:px-8">
      <section className="pb-10 pt-8 sm:pt-10">
        <h1 className="lm-serif -ml-1 whitespace-nowrap text-[clamp(56px,18.6vw,262px)] leading-[0.84]">
          Lucía Marín
        </h1>
        <div className="mt-6 grid gap-6 border-t border-[#141414] pt-5 lg:grid-cols-12">
          <p className="text-lg leading-snug lg:col-span-5 lg:text-[21px]">
            Diseñadora y fotógrafa en Valencia. Hago identidades, campañas y libros para marcas pequeñas
            <span className="lm-serif italic text-[1.2em]"> que cuidan cómo se hacen las cosas.</span>
          </p>
          <p className="text-[15px] leading-relaxed text-[#55575D] lg:col-span-3 lg:col-start-7">
            Fotografía de espacios y producto,<br />identidad visual, dirección de arte<br />y diseño editorial.
          </p>
          <div className="lg:col-span-3 lg:col-start-10 lg:text-right">
            <p className="inline-flex items-center gap-2 text-[15px]">
              <span className="h-2 w-2 rounded-full bg-[#2633C9]" aria-hidden /> {STUDIO.availability}
            </p>
            <button onClick={() => go({ name: 'contacto' })} className="mt-3 block border-b border-[#141414] pb-0.5 text-[15px] hover:border-[#2633C9] hover:text-[#2633C9] lg:ml-auto">
              Contar mi proyecto
            </button>
          </div>
        </div>
      </section>

      <div className="z-30 -mx-5 flex flex-wrap items-center gap-2 bg-[#F5F5F2] px-5 py-3 sm:sticky sm:top-[61px] sm:-mx-8 sm:px-8">
        <div className="flex flex-wrap gap-2" role="group" aria-label="Filtrar por disciplina">
          {(['Todo', ...DISCIPLINES] as Filter[]).map(d => (
            <Pill key={d} active={filter === d} onClick={() => setFilter(d)} count={count(d)}>{d}</Pill>
          ))}
        </div>
        <div className="ml-auto flex w-full items-center gap-2 sm:w-auto">
          <label className="relative flex-1 sm:w-56 sm:flex-none">
            <span className="sr-only">Buscar proyecto o cliente</span>
            <Search size={16} className="absolute left-0 top-1/2 -translate-y-1/2 text-[#55575D]" />
            <input value={q} onChange={e => setQ(e.target.value)} placeholder="Buscar" className="lm-field text-[15px]" style={{ paddingLeft: 24 }} />
          </label>
          <div className="flex border border-[#C9C9C2]" role="group" aria-label="Vista">
            <button onClick={() => setView('rejilla')} aria-pressed={view === 'rejilla'} aria-label="Ver en rejilla" className={clsx('p-2', view === 'rejilla' ? 'bg-[#141414] text-white' : 'hover:bg-[#E9E9E4]')}><LayoutGrid size={16} /></button>
            <button onClick={() => setView('indice')} aria-pressed={view === 'indice'} aria-label="Ver como índice" className={clsx('p-2', view === 'indice' ? 'bg-[#141414] text-white' : 'hover:bg-[#E9E9E4]')}><List size={16} /></button>
          </div>
          <button onClick={onAdd} className="inline-flex items-center gap-1.5 border border-[#141414] px-3 py-[7px] text-sm hover:bg-[#141414] hover:text-white">
            <Plus size={15} /> Añadir proyecto
          </button>
        </div>
      </div>

      {list.length === 0 && (
        <div className="py-24 text-center">
          <p className="lm-serif text-4xl">Nada por aquí con «{q || filter}».</p>
          <button onClick={() => { setQ(''); setFilter('Todo'); }} className="mt-5 inline-flex items-center gap-1.5 border-b border-[#141414] pb-0.5"><X size={15} /> Quitar filtros</button>
        </div>
      )}

      {view === 'rejilla' ? (
        <div key={filter + q} className="lm-fade grid grid-cols-1 gap-x-8 gap-y-14 pt-6 sm:grid-cols-2 lg:grid-cols-12">
          {list.map((p, i) => (
            <article key={p.id} className={clsx('lm-card', LAYOUT[i % LAYOUT.length].replace(/aspect-\S+/, ''))}>
              <button onClick={() => open(p)} className="block w-full text-left" aria-label={`Abrir ${p.title}`}>
                <Photo name={p.cover} eager={i < 3} className={LAYOUT[i % LAYOUT.length].match(/aspect-\S+/)?.[0]} />
              </button>
              <div className="mt-3 flex items-baseline justify-between gap-4">
                <button onClick={() => open(p)} className="lm-serif lm-link text-left text-[28px] leading-tight">{p.title}</button>
                <span className="lm-num shrink-0 text-sm text-[#55575D]">{p.year}</span>
              </div>
              <p className="mt-1 text-[15px] text-[#55575D]">{p.client} · {p.discipline}</p>
            </article>
          ))}
        </div>
      ) : (
        <div key={filter + q} className="lm-fade pt-4" onMouseLeave={() => setHover(null)}>
          {list.map(p => (
            <button
              key={p.id}
              onClick={() => open(p)}
              onMouseMove={e => setHover({ img: p.cover, x: e.clientX, y: e.clientY })}
              className="group grid w-full grid-cols-[52px_1fr] items-baseline gap-x-4 border-b border-[#D8D8D2] py-5 text-left sm:grid-cols-[72px_1.6fr_1fr_1fr]"
            >
              <span className="lm-num text-sm text-[#55575D]">{p.year}</span>
              <span className="lm-serif text-[32px] leading-tight transition-colors group-hover:text-[#2633C9] sm:text-[44px]">{p.title}</span>
              <span className="col-start-2 text-[15px] text-[#55575D] sm:col-start-auto">{p.client}</span>
              <span className="col-start-2 text-[15px] sm:col-start-auto sm:text-right">{p.discipline}</span>
            </button>
          ))}
          {hover && (
            <img
              src={IMG(hover.img)} alt="" aria-hidden
              className="pointer-events-none fixed z-30 hidden h-[220px] w-[170px] object-cover shadow-xl lg:block"
              style={{ left: hover.x + 24, top: hover.y - 110 }}
            />
          )}
        </div>
      )}
    </div>
  );
}

import { useEffect, type ReactNode } from 'react';
import clsx from 'clsx';
import { X } from 'lucide-react';
import { IMG } from '../data/images';
import { PHOTOS } from '../data/projects';

export function Photo({ name, className, eager, alt }: { name: string; className?: string; eager?: boolean; alt?: string }) {
  return (
    <div className={clsx('lm-photo', className)}>
      <img
        src={IMG(name)}
        alt={alt ?? PHOTOS[name] ?? 'Fotografía del proyecto'}
        loading={eager ? 'eager' : 'lazy'}
        className="h-full w-full object-cover"
      />
    </div>
  );
}

export function Toast({ text, onClose }: { text: string | null; onClose: () => void }) {
  useEffect(() => {
    if (!text) return;
    const t = setTimeout(onClose, 3200);
    return () => clearTimeout(t);
  }, [text, onClose]);
  if (!text) return null;
  return (
    <div role="status" className="lm-pop fixed bottom-5 left-5 z-[60] max-w-[calc(100vw-2.5rem)] bg-[#141414] px-5 py-3 text-sm text-white shadow-lg">
      {text}
    </div>
  );
}

export function Modal({ title, onClose, children, wide }: { title: string; onClose: () => void; children: ReactNode; wide?: boolean }) {
  useEffect(() => {
    const k = (e: KeyboardEvent) => { if (e.key === 'Escape') onClose(); };
    window.addEventListener('keydown', k);
    const prev = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    return () => { window.removeEventListener('keydown', k); document.body.style.overflow = prev; };
  }, [onClose]);
  return (
    <div className="fixed inset-0 z-50 flex items-end justify-center bg-[#141414]/50 sm:items-center sm:p-6" onMouseDown={onClose}>
      <div
        role="dialog" aria-modal="true" aria-label={title}
        onMouseDown={e => e.stopPropagation()}
        className={clsx('lm-pop max-h-[92vh] w-full overflow-y-auto bg-[#F5F5F2] p-6 sm:p-9', wide ? 'max-w-3xl' : 'max-w-lg')}
      >
        <div className="mb-6 flex items-start justify-between gap-4">
          <h2 className="lm-serif text-4xl leading-none">{title}</h2>
          <button onClick={onClose} aria-label="Cerrar" className="-m-2 p-2 text-[#55575D] hover:text-[#141414]"><X size={22} /></button>
        </div>
        {children}
      </div>
    </div>
  );
}

export function Field({ label, error, children, hint }: { label: string; error?: string; hint?: string; children: ReactNode }) {
  return (
    <label className="block">
      <span className="text-sm text-[#55575D]">{label}</span>
      {children}
      {error ? <span className="mt-1.5 block text-sm text-[#B3261E]">{error}</span>
        : hint ? <span className="mt-1.5 block text-sm text-[#55575D]">{hint}</span> : null}
    </label>
  );
}

export function Pill({ active, onClick, children, count }: { active: boolean; onClick: () => void; children: ReactNode; count?: number }) {
  return (
    <button
      onClick={onClick}
      aria-pressed={active}
      className={clsx(
        'rounded-full border px-4 py-1.5 text-[15px] transition-colors',
        active ? 'border-[#2633C9] bg-[#2633C9] text-white' : 'border-[#C9C9C2] text-[#141414] hover:border-[#141414]',
      )}
    >
      {children}
      {count !== undefined && <sup className={clsx('lm-num ml-1 text-[11px]', active ? 'text-white/80' : 'text-[#55575D]')}>{count}</sup>}
    </button>
  );
}

