import { useCallback, useEffect, useState } from 'react';
import type { Inquiry, Project } from './types';
import { SEED_PROJECTS } from '../data/projects';

const KEY = 'lucia-marin:portafolio:v1';

export type Data = { projects: Project[]; inquiries: Inquiry[] };

function seed(): Data {
  return {
    projects: SEED_PROJECTS,
    inquiries: [
      {
        id: 'q1', name: 'Marta Soler', email: 'marta@hornosoler.es', company: 'Horno Soler', kind: 'Identidad visual',
        budget: '3.000 – 6.000 €', when: '2027-02', message: 'Abrimos un segundo obrador en Ruzafa y queremos renovar la marca sin perder lo que la gente reconoce.',
        createdAt: Date.now() - 864e5 * 3,
      },
    ],
  };
}

function load(): Data {
  try {
    const raw = localStorage.getItem(KEY);
    if (raw) {
      const d = JSON.parse(raw) as Data;
      if (Array.isArray(d.projects) && Array.isArray(d.inquiries)) return d;
    }
  } catch { /* datos dañados: se usan los de ejemplo */ }
  return seed();
}

export function useStore() {
  const [data, setData] = useState<Data>(load);

  useEffect(() => {
    try { localStorage.setItem(KEY, JSON.stringify(data)); } catch { /* almacenamiento no disponible */ }
  }, [data]);

  const saveProject = useCallback((p: Project) => setData(d => {
    const exists = d.projects.some(x => x.id === p.id);
    return { ...d, projects: exists ? d.projects.map(x => (x.id === p.id ? p : x)) : [p, ...d.projects] };
  }), []);

  const deleteProject = useCallback((id: string) => setData(d => ({ ...d, projects: d.projects.filter(x => x.id !== id) })), []);

  const addInquiry = useCallback((q: Inquiry) => setData(d => ({ ...d, inquiries: [q, ...d.inquiries] })), []);
  const deleteInquiry = useCallback((id: string) => setData(d => ({ ...d, inquiries: d.inquiries.filter(x => x.id !== id) })), []);

  const reset = useCallback(() => setData(seed()), []);

  return { ...data, saveProject, deleteProject, addInquiry, deleteInquiry, reset };
}

export type Store = ReturnType<typeof useStore>;

/** Preferencia sencilla guardada en localStorage (vista de rejilla/índice, filtro…). */
export function usePref<T extends string>(key: string, initial: T): [T, (v: T) => void] {
  const [v, setV] = useState<T>(() => {
    try { return (localStorage.getItem('lucia-marin:' + key) as T) || initial; } catch { return initial; }
  });
  const set = useCallback((x: T) => {
    setV(x);
    try { localStorage.setItem('lucia-marin:' + key, x); } catch { /* sin almacenamiento */ }
  }, [key]);
  return [v, set];
}

